using System.Runtime.InteropServices;

namespace NG.Velox.Interpolation.Data
{
    /// <summary>
    /// A single point in the interpolated trajectory.
    /// </summary>
    /// <remarks>
    /// <para>
    /// Contains 3D coordinates (X, Y, Z), instantaneous velocity, and timestamp.
    /// Size is 40 bytes (5 doubles) with 8-byte alignment.
    /// </para>
    /// <para>
    /// Points are generated by the interpolator and represent the actual path
    /// the machine will follow, including acceleration/deceleration profiles.
    /// </para>
    /// </remarks>
    [StructLayout(LayoutKind.Sequential, Pack = 8)]
    public readonly struct TrajectoryPoint
    {
        /// <summary>
        /// X coordinate (mm).
        /// </summary>
        public readonly double X;

        /// <summary>
        /// Y coordinate (mm).
        /// </summary>
        public readonly double Y;

        /// <summary>
        /// Z coordinate (mm).
        /// </summary>
        public readonly double Z;

        /// <summary>
        /// Instantaneous velocity at this point (mm/s).
        /// </summary>
        public readonly double Velocity;

        /// <summary>
        /// Cumulative time from start of trajectory (seconds).
        /// </summary>
        public readonly double TimeStamp;

        /// <summary>
        /// Creates a new trajectory point.
        /// </summary>
        /// <param name="x">X coordinate (mm).</param>
        /// <param name="y">Y coordinate (mm).</param>
        /// <param name="z">Z coordinate (mm).</param>
        /// <param name="velocity">Velocity (mm/s).</param>
        /// <param name="timeStamp">Timestamp (seconds).</param>
        public TrajectoryPoint(double x, double y, double z, double velocity, double timeStamp)
        {
            X = x;
            Y = y;
            Z = z;
            Velocity = velocity;
            TimeStamp = timeStamp;
        }
    }
}